#include <list>
#include <iostream>

int main() {
    std::list<int> l1 = {1, 2, 3};
    std::list<int> l2 = {4, 5, 6};

    // Move all of l2 to the beginning of l1 (O(1))
    l1.splice(l1.begin(), l2);

    // l1 is now {4, 5, 6, 1, 2, 3}, l2 is empty

    std::list<int> l3 = {7, 8, 9};
    auto it_8 = std::next(l3.begin()); // Iterator pointing to 8

    // Move element '8' from l3 to the end of l1 (O(1))
    l1.splice(l1.end(), l3, it_8);
    // l1: {4, 5, 6, 1, 2, 3, 8}
    // l3: {7, 9}
}
